complexParameter.core:text:
def bodyId = _source.p.guid.value()

def polys = []
_source.links.soilbody_geom.each { part ->
  def g = part.p.geom.value()
  def geometry = g?.geometry
  if (geometry != null) {
    for (int i = 0; i < geometry.numGeometries; i++) {
      polys << geometry.getGeometryN(i)
    }
  }
}
def geomWkt = null
if (!polys.isEmpty()) {
  def gf = polys[0].factory
  geomWkt = gf.createMultiPolygon(polys as org.locationtech.jts.geom.Polygon[]).toText()
}

def label = _source.p.soilbodylabel.value()
def locid = _source.p.inspireid_localid.value()
def ns = _source.p.inspireid_namespace.value()
def verid = _source.p.inspireid_versionid.value()
def beg = _source.p.beginlifespanversion.value()
def end = _source.p.endlifespanversion.value()

_target {
  id(bodyId)
  method('post')
  url('Features')
  atomicityGroup('g1')
  body {
    name('soilbody:' + bodyId)
    encodingType('application/geo+json')
    FeatureTypes {
      '@id'('$ft-soilbody')
    }
    properties {
      guid(bodyId)
      source_format('GeoPackage')
      source_media_type('application/geopackage+sqlite3')
      source_table('soilbody')
      srs('EPSG:3035')
      if (geomWkt) { geometry_3035(geomWkt) }
      if (label) { soilbodylabel(label) }
      if (locid) { inspireid_localid(locid) }
      if (ns) { inspireid_namespace(ns) }
      if (verid) { inspireid_versionid(verid) }
      if (beg) { beginlifespanversion(beg.toString()) }
      if (end) { endlifespanversion(end.toString()) }
    }
  }
}

def profileId = _source.p.guid.value()

def plot = _source.links.soilplot.first()
def plotLoc = plot?.p?.soilplotlocation?.value()
def geometry = plotLoc?.geometry
def geomWkt = geometry?.toText()

def wrbRecords = []
_source.links.wrbqualifiergroup_profile.each { wg ->
  def wgtGuid = wg.p.guid_wrbqualifiergrouptype.value()
  def wgt = wg.links.wrbqualifiergrouptype.first()
  wrbRecords << [
    qualifiergrouptype_guid: wgtGuid,
    qualifierposition: wg.p.qualifierposition.value(),
    wrbversion: wgt?.p?.wrbversion?.value(),
    qualifierplace: wgt?.p?.qualifierplace?.value(),
    wrbqualifier: wgt?.p?.wrbqualifier?.value(),
    wrbspecifier_1: wgt?.p?.wrbspecifier_1?.value(),
    wrbspecifier_2: wgt?.p?.wrbspecifier_2?.value()
  ]
}

def derivedRecords = []
_source.links.isderivedfrom.each { d ->
  derivedRecords << [ source_guid: d.p.guid_related.value() ]
}

def locid = _source.p.inspireid_localid.value()
def ns = _source.p.inspireid_namespace.value()
def verid = _source.p.inspireid_versionid.value()
def beg = _source.p.beginlifespanversion.value()
def end = _source.p.endlifespanversion.value()
def vf = _source.p.validfrom.value()
def vt = _source.p.validto.value()
def isder = _source.p.isderived.value()
def isorig = _source.p.isoriginalclassification.value()
def locident = _source.p.localidentifier.value()
def wrbver = _source.p.wrbversion.value()
def wrbrsg = _source.p.wrbreferencesoilgroup.value()

_target {
  id(profileId)
  method('post')
  url('Features')
  atomicityGroup('g1')
  body {
    name('soilprofile:' + profileId)
    encodingType('application/geo+json')
    FeatureTypes {
      '@id'('$ft-soilprofile')
    }
    properties {
      guid(profileId)
      source_format('GeoPackage')
      source_media_type('application/geopackage+sqlite3')
      source_table('soilprofile')
      srs('EPSG:3035')
      if (geomWkt) { geometry_3035(geomWkt) }
      if (locid) { inspireid_localid(locid) }
      if (ns) { inspireid_namespace(ns) }
      if (verid) { inspireid_versionid(verid) }
      if (beg != null) { beginlifespanversion(beg.toString()) }
      if (end != null) { endlifespanversion(end.toString()) }
      if (vf != null) { validfrom(vf.toString()) }
      if (vt != null) { validto(vt.toString()) }
      if (isder != null) { isderived(isder) }
      if (isorig != null) { isoriginalclassification(isorig) }
      if (locident) { localidentifier(locident) }
      if (wrbver) { wrbversion(wrbver) }
      if (wrbrsg) { wrbreferencesoilgroup(wrbrsg) }

      if (!wrbRecords.isEmpty()) {
        wrb_qualifiers {
          source_table('wrbqualifiergroup_profile')
          related_source_table('wrbqualifiergrouptype')
          wrbRecords.each { rec ->
            records {
              if (rec.qualifiergrouptype_guid) { qualifiergrouptype_guid(rec.qualifiergrouptype_guid) }
              if (rec.qualifierposition != null) { qualifierposition(rec.qualifierposition) }
              if (rec.wrbversion) { wrbversion(rec.wrbversion) }
              if (rec.qualifierplace) { qualifierplace(rec.qualifierplace) }
              if (rec.wrbqualifier) { wrbqualifier(rec.wrbqualifier) }
              if (rec.wrbspecifier_1) { wrbspecifier_1(rec.wrbspecifier_1) }
              if (rec.wrbspecifier_2) { wrbspecifier_2(rec.wrbspecifier_2) }
            }
          }
        }
      }

      if (!derivedRecords.isEmpty()) {
        isderivedfrom {
          source_table('isderivedfrom')
          related_source_table('soilprofile')
          derivedRecords.each { rec ->
            records {
              if (rec.source_guid) { source_guid(rec.source_guid) }
              isderived(true)
            }
          }
        }
      }
    }
  }
}
